const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([177.5, 64.7]);
  const region = point.buffer(5000); // 5km radius around Onemen Bay

  const date1Start = '2025-08-07';
  const date1End = '2025-08-11';
  const date2Start = '2025-09-09';
  const date2End = '2025-09-13';

  // 2. Data Acquisition - Sentinel-2
  function maskS2clouds(image) {
    const scl = image.select('SCL');
    const mask = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10));
    return image.updateMask(mask);
  }

  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate(date1Start, date1End)
    .map(maskS2clouds);

  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate(date2Start, date2End)
    .map(maskS2clouds);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Aug 2025 Images: ${size1}`);
  console.log(`Sep 2025 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('Trying Landsat 8/9 fallback...');

    function maskL8clouds(image) {
      const qa = image.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
      return image.updateMask(mask);
    }

    col1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
      .filterBounds(region)
      .filterDate(date1Start, date1End)
      .map(maskL8clouds);

    col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
      .filterBounds(region)
      .filterDate(date2Start, date2End)
      .map(maskL8clouds);

    const size1L = await col1.size().getInfo();
    const size2L = await col2.size().getInfo();

    console.log(`Landsat Aug: ${size1L}, Sep: ${size2L}`);

    if (size1L === 0 || size2L === 0) {
      console.log('No data available for one or both dates.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Calculate NDVI
  function addNDVI(image) {
    const nir = image.select('B8');
    const red = image.select('B4');
    const ndvi = nir.subtract(red).divide(nir.add(red)).rename('NDVI');
    return image.addBands(ndvi);
  }

  const img1 = col1.map(addNDVI).select('NDVI').median();
  const img2 = col2.map(addNDVI).select('NDVI').median();

  // 4. Check pixel counts
  const count1 = await img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2 = await img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Aug pixels: ${count1}, Sep pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate mean NDVI
  const ndvi1 = await img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const ndvi2 = await img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Aug NDVI: ${ndvi1}`);
  console.log(`Sep NDVI: ${ndvi2}`);

  // 6. Validation & Answer
  if (ndvi1 === null || ndvi2 === null || isNaN(ndvi1) || isNaN(ndvi2) || 
      ndvi1 < -1 || ndvi1 > 1 || ndvi2 < -1 || ndvi2 > 1) {
    console.log('Invalid NDVI calculation.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (ndvi1 > ndvi2) {
    console.log('More green vegetation in August than September.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Not more green vegetation in August.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
